def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_defects = sum(1 for h in history if h[1] == 'D')

    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        if history[1][1] == 'D' and history[0][1] == 'D':
            return 'D'
        return 'C'
    if n == 3:
        return 'D'

    if opp_defects >= n - 2:
        return 'D'

    if n == 4:
        return 'C'

    opp_reaction = history[4][1]
    unprovoked = sum(1 for me, opp in history if me == 'C' and opp == 'D')

    if opp_reaction == 'C':
        return 'D' if n % 2 == 1 else 'C'
    else:
        if unprovoked >= 2:
            return 'D' if n % 3 == 0 else 'C'
        else:
            return 'D' if n % 4 == 0 else 'C'
